          "answerText": "Сильніша сульфатна кислота витісняє летку етанову кислоту із солі. Етанол за нагрівання з концентрованою H2SO4 за близько 140 °C міжмолекулярно дегідратується до діетилового етеру. Для спостережень використовують окремі проби.",
