          "answerText": "В молекуле жира три остатка длинноцепочечных кислот соединены с глицеролом тремя естерными связями. Длинные углеводородные цепи делают жир гидрофобным и малолетучим; гидролиз остаётся возможным, как и у малых естеров.",
